const footer = {
  id:'footer',
  copy:{
    copyright: '©&nbsp;Old Mates Cranes & Rigging',
    by: <>'Keeping it safe and simple is our guiding principle whenever we approach any lift. Be it the first time or the thousandth we ensure it is the safest and most efficient way to complete the lift.<br/><br/>We encourage our crane crew to talk to clients about what it is there lifting, what it does and where it’s going to ensure they are best equipped to tackle the task ahead.'</>
  }
};

const Footer = () =>  (
    <section className='container-fluid p-0 bg-charcoal' id={footer.id}>
      <div className='row px-4 g-0'>
        <div className='col'>
          {footer.copy.title}
          {footer.copy.copy}
        </div>
      </div>
    </section>
)

export default Footer;
